<template>
  <Dialog>
    <DialogTrigger as-child>
      <Button :disabled="disabled" :prepend-icon="FileUpIcon">Export</Button>
    </DialogTrigger>
    <DialogContent>
      <DialogHeader>
        <DialogTitle>Export Users List</DialogTitle>
        <DialogDescription>
          You can export the list of users with certain role(s) in CSV or XLS format.
        </DialogDescription>
      </DialogHeader>
      <div class="flex flex-col gap-4">
        <LabeledSelect v-model="exportFormat" :items="exportFormats" label="Format" />
        <LabeledSelectMultiple
          v-model="selectedRoles"
          :items="allRoles"
          placeholder="Exports all user roles"
          label="Roles"
        />
      </div>
      <DialogFooter>
        <DialogClose as-child>
          <Button variant="outline">Cancel</Button>
        </DialogClose>
        <Button :loading="isExportUsersList" @click="exportUsers">Export</Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { userRoles } from '~/constants/users/userRoles';
import { useExportUsersList } from '~/mutations/users/exportUsersList';
import type { UserRole } from '~/client';
import { FileUpIcon } from 'lucide-vue-next';
import { exportFormats } from '~/constants/export';

interface Props {
  exportType?: 'all' | 'byProject';
  projectId?: string;
  disabled?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  exportType: 'all',
  projectId: undefined,
});

const exportFormat = ref<SelectItem<'csv' | 'xls'>>({ name: 'CSV', value: 'csv' });
const selectedRoles = ref<SelectItem<UserRole>[] | null>([]);

const { isAdmin, isManager } = useUserRole();

const allRoles: SelectItem<UserRole>[] = [
  ...Object.entries(userRoles)
    .map(([key, { name }]) => ({ name, value: key as UserRole }))
    .filter(({ value }) => (isManager.value && value !== 'admin') || isAdmin.value),
];

const { exportUsersList, isExportUsersList, data } = useExportUsersList();

async function exportUsers() {
  const userRoles: UserRole[] =
    selectedRoles.value && selectedRoles.value?.length > 0
      ? selectedRoles.value.map((role) => role.value as UserRole)
      : allRoles.map((role) => role.value as UserRole);
  await exportUsersList({
    file_type: exportFormat.value.value as 'csv' | 'xls',
    roles: userRoles,
    ...(props.exportType === 'byProject' && props.projectId ? { project_id: props.projectId } : {}),
  });
  if (data.value?.id)
    await navigateTo({
      name: 'exports-id',
      params: { id: data.value.id },
    });
}
</script>
