import { createExportUsersJob, type UsersExportRequest, type CreateExportUsersJobResponse } from '~/client';

export const useExportUsersList = defineMutation(() => {
  const {
    mutateAsync: exportUsersList,
    asyncStatus,
    data,
  } = useMutation({
    mutation: (data: NonNullable<UsersExportRequest>): Promise<CreateExportUsersJobResponse> =>
      createExportUsersJob({ composable: '$fetch', body: ref(data) }),
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    exportUsersList,
    isExportUsersList: computed(() => asyncStatus.value === 'loading'),
    data,
  };
});
