<template>
  <div class="flex flex-col gap-1.5 w-full">
    <p v-if="label" class="text-sm font-medium">{{ label }}</p>
    <Select v-model="value" class="border-border" multiple>
      <SelectTrigger class="gap-2 relative">
        <SelectValue class="text-foreground">
          <span v-if="value && value.length > 0">
            {{ selectedPreLabel ?? '' }}
            {{ value.map((item) => item.name ?? item.value).join(', ') }}
          </span>
          <span v-else class="text-muted-foreground">{{ placeholder }}</span>
        </SelectValue>
      </SelectTrigger>
      <SelectContent>
        <p v-if="!items.length" class="px-3 text-sm text-accent-foreground select-none">No items to select</p>
        <SelectItem v-for="(item, index) in items" v-else :key="index" :value="item">
          {{ item.name ?? item.value }}
        </SelectItem>
      </SelectContent>
    </Select>
  </div>
</template>

<script setup lang="ts">
interface Props {
  label?: string;
  items: SelectItem[];
  placeholder?: string;
  selectedPreLabel?: string;
}

defineProps<Props>();
const value = defineModel<SelectItem[] | null>({ default: null });
</script>

<style lang="scss" scoped></style>
